        <div class="cards">
          <div class="card">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div class="tag">Clarity Track</div>
                <h3 style="margin:8px 0 0">Sharpen a daily focus window</h3>
              </div>
              <div class="program-price">$220 — program pack</div>
            </div>
            <div class="program-list">
              <div style="color:var(--muted)">Week 1: Tiny focus anchors • Week 2: Ritualized start • Checkpoint: sustained 90-minute focus block</div>
            </div>
            <a class="cta" href="book.html" style="display:inline-block;margin-top:10px;padding:10px 12px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none">Begin clarity</a>
          </div>

          <div class="card">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div class="tag">Rhythm Course</div>
                <h3 style="margin:8px 0 0">Establish a practical daily rhythm</h3>
              </div>
              <div class="program-price">Custom pricing</div>
            </div>
            <p style="color:var(--muted);margin-top:8px">Includes weekly check-ins, micro-tasks, and a simple calendar redesign you can keep.</p>
            <a class="cta" href="contact.html" style="display:inline-block;margin-top:10px;padding:10px 12px;background:#4a90e2;color:#fff;border-radius:8px;text-decoration:none">Ask about rhythm</a>
