  <script>
    // Mini readiness meter: maps choices to a quick % and suggested plan
    const meter = document.getElementById('meter');
    const readout = document.getElementById('readout');
    const suggest = document.getElementById('suggest');
    const target = document.getElementById('target');

    function updateMeter(){
      const t = target.value;
      // naive heuristic: look for local factors in storage (simulated)
      const known = JSON.parse(localStorage.getItem('wc_status')||'{}');
      let score = 50; // baseline
      if(known[t]) score = Math.min(90, Math.max(30, known[t]));
      // pick color and message
      let pct = score + '%';
      meter.style.setProperty('--pct', pct);
      meter.textContent = pct;
      if(score>75){ readout.textContent = 'High readiness'; suggest.textContent = 'You can begin with a focused two-week practice.'; }
      else if(score>50){ readout.textContent = 'Good readiness'; suggest.textContent = 'Start with a one-week trial and three micro-tasks.'; }
      else{ readout.textContent = 'Low readiness'; suggest.textContent = 'Begin with tiny daily experiments to build momentum.'; }
    }

    // Simulate stored status for demo
    if(!localStorage.getItem('wc_status')){
      localStorage.setItem('wc_status', JSON.stringify({focus:68,sleep:42,movement:55}));
    }
    target.addEventListener('change', updateMeter);
    updateMeter();

    // Rotating program quotes
    const quotes = [
      '“The Clarity Track gave me a usable focus block.” — R.',
      '“Reset Sprint moved one habit without collapsing my schedule.” — J.',
      '“Team templates brought a shared language to our week.” — L.'
    ];
    let qidx = 0;
    const qEl = document.getElementById('prog-quote');
    function showQuote(i){ qEl.textContent = quotes[i]; }
    document.getElementById('q-prev').addEventListener('click',()=>{ qidx=(qidx-1+quotes.length)%quotes.length; showQuote(qidx); });
    document.getElementById('q-next').addEventListener('click',()=>{ qidx=(qidx+1)%quotes.length; showQuote(qidx); });
    setInterval(()=>{ qidx=(qidx+1)%quotes.length; showQuote(qidx); },4000);
  </script>
